<script setup>
// 打卡按钮皮肤：根据已装备 skin 渲染对应款式，打卡成功后播放该皮肤的“已完成”动画。
// 参考组件库 打卡/按钮装扮 下的模板（笔/太空人/开灯/心星摇摆/动感涂鸦按原模板还原；
// 椰滩海洋为日落海景版，结构与交互动效按模板，艺术图为等价 SVG 场景）。
import { ref, computed, watch, nextTick } from "vue";
import { customButtonById } from "../lib/skins.js";

const props = defineProps({
  skin: { type: String, default: "bi" }, // 皮肤 id
  done: { type: Boolean, default: false }, // 今日是否已打卡
  disabled: { type: Boolean, default: false },
  demo: { type: Boolean, default: false } // 商场预览：点按只切换动画，不触发打卡
});

const emit = defineEmits(["checkin"]);

// 触发“已完成”动画：done 变 true 时加 active/checked，变 false 移除
const active = ref(false);
const flash = ref(0);
watch(
  () => props.done,
  (v) => {
    if (v) {
      flash.value++;
      nextTick(() => {
        active.value = true;
      });
    } else {
      active.value = false;
    }
  },
  { immediate: true }
);

const label = ref(active.value ? "今日已打卡" : "今日打卡");
watch(active, (v) => {
  label.value = v ? "今日已打卡" : "今日打卡";
});

// 自定义按钮皮肤（后台模板上传生成）：按参数渲染
const customBtn = computed(() => customButtonById(props.skin));
const customStyle = computed(() => {
  const st = (customBtn.value && customBtn.value.style) || {};
  return {
    background: st.bg || "linear-gradient(180deg,#3f7d6b,#2b5d4f)",
    color: st.color || "#fff",
    borderRadius: st.radius || "18px",
    minWidth: st.minW || "230px",
    minHeight: st.minH || "72px",
    fontSize: st.fontSize || "18px",
    border: st.border || "1px solid rgba(255,255,255,.2)",
    boxShadow: st.shadow || "0 10px 18px rgba(0,0,0,.2)",
    padding: "0 24px",
    fontWeight: "800"
  };
});
const customLabel = computed(() =>
  (customBtn.value && customBtn.value.style && customBtn.value.style.label) || label.value
);

function onClick() {
  if (props.disabled) return;
  if (props.demo) {
    active.value = !active.value;
    return;
  }
  emit("checkin");
}
</script>

